CREATE TABLE employees(user_id INTEGER PRIMARY KEY,name TEXT NOT NULL,role TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,started INTEGER NOT NULL DEFAULT 0);
CREATE TABLE tasks(id INTEGER PRIMARY KEY,title TEXT NOT NULL,creator INTEGER NOT NULL REFERENCES employees(user_id),assignee INTEGER NOT NULL REFERENCES employees(user_id),due_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'new',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE history(id INTEGER PRIMARY KEY,task_id INTEGER NOT NULL REFERENCES tasks(id),actor INTEGER NOT NULL,action TEXT NOT NULL,created_at INTEGER NOT NULL);
